    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'approve', label: 'Approve' },
    { action: 'reject', label: 'Reject' },
    { action: 'void', label: 'Void' },
  ];

  protected fieldId(field: string): string {
    return `claim-${this.personId()}-${field}`;
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected checked(event: Event): boolean {
    return (event.target as HTMLInputElement).checked;
  }

  /** What is due on the claim at the rate in force on the claim's date of the person's grade in force
   *  then; n/a when no rate of that grade applies then; never below the sheet's floor; with its late charge added while it is
   *  overdue. A claim settled at a rate keeps what was due on it then; one settled without a rate
   *  fixed nothing. */
  protected dueOf(claim: Claim): string {
    const late = { terms: this.terms(), today: this.session.today(), latePct: this.latePct() };
    const rounding = { policyDate: this.policyDate(), claims: this.claims() };
    const due = claimShownCents(claim, this.rates(), this.grades(), this.floor(), late, rounding);
    return due === null ? 'n/a' : money(due);
  }

  protected dueBy(claim: Claim): string {
    return dueByOf(claim, this.terms());
  }

  protected isOverdue(claim: Claim): boolean {
    return overdue(claim, this.terms(), this.session.today());
  }

  /** The name of the period whose dates contain the claim's date; empty when none does. */
  protected periodOf(claim: Claim): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  /** Open the claim's editor; only a DRAFT can be edited, so the edit of any other claim is refused with
   *  an error on the claim (an open claim is changed by voiding it and adding a new one). */
  protected edit(claim: Claim): void {
    this.clearRowError(claim.id);
    if (claim.status !== 'DRAFT') {
      if (this.editingId() === claim.id) this.reset();
      this.rowErrors.update((errors) => ({
        ...errors,
        [claim.id]: 'Only a draft claim can be edited; void it and add a new one instead.',
      }));
      return;
    }
    this.editingId.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.corrects.set(claim.corrects ?? '');
    this.error.set(null);
  }

  protected setRejectReason(id: number, reason: string): void {
    this.rejectReasons.update((reasons) => ({ ...reasons, [id]: reason }));
    this.clearRowError(id);
  }

  /** Change the claim's status; a change its status does not allow, a settle by the user who opened
   *  the claim, an approve by a user who is not a steward or who opened the claim, a reject by a user
   *  who is not a steward or without a one-word reason, is refused with an error. A clerk's settle of
   *  a claim whose due is above the clerk limit leaves it PENDING for a steward. */
  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
    this.clearRowError(claim.id);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
    if (action === 'reject' && !/^\S{1,200}$/.test(reason)) {
      this.rowErrors.update((errors) => ({ ...errors, [claim.id]: 'Type a one-word reason to reject that claim.' }));
      return;
    }
    try {
      const changed = await this.service.act(sheet, claim.id, action, action === 'reject' ? reason : undefined);
      if (this.session.sheetId() !== sheet) return;
      if (action === 'reject') this.rejectReasons.update(({ [claim.id]: _, ...rest }) => rest);
      this.saved.emit(changed);
    } catch (e) {
      if (this.session.sheetId() !== sheet) return;
      this.rowErrors.update((errors) => ({
        ...errors,
        [claim.id]: e instanceof HttpErrorResponse && e.status === 403
          ? action === 'settle'
            ? 'You opened that claim, so another user must settle it.'
            : `Only a steward${action === 'approve' ? ' who did not open that claim' : ''} can ${action} it.`
          : e instanceof HttpErrorResponse && e.status === 400
          ? 'Type a one-word reason to reject that claim.'
          : e instanceof HttpErrorResponse && e.status === 423
          ? 'That claim is dated in a closed period.'
          : `That claim cannot be ${PAST[action]} in its status.`,
      }));
    }
  }

  private clearRowError(id: number): void {
    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.amount.set('');
    this.date.set('');
    this.note.set('');
    this.corrects.set('');
    this.error.set(null);
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const amount = this.amount().trim();
    if (!AMOUNT.test(amount)) {
      this.error.set('Type an amount with up to two decimals.');
      return;
    }
    const corrects = this.corrects().trim();
    if (corrects !== '' && !NUMBER.test(corrects)) {
      this.error.set('Type the number of the claim it corrects.');
      return;
    }
    const fields = {
      amount,
      date: this.date().trim() || null,
      note: this.note(),
      corrects: corrects === '' ? null : corrects,
    };
    const id = this.editingId();
    this.submitting = true;
    try {
      const claim =
        id === null
          ? await this.service.add(sheet, this.personId(), fields)
          : await this.service.update(sheet, id, fields);
      if (this.session.sheetId() !== sheet) return;
      this.saved.emit(claim);
      this.reset();
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 423
          ? 'A claim dated in a closed period cannot be changed.'
          : e instanceof HttpErrorResponse && e.status === 422
            ? 'A claim cannot be dated after the person retired.'
          : e instanceof HttpErrorResponse && e.status === 400
            ? 'A negative amount is a correction: name the number of a settled claim of this person it corrects (and only a correction names one).'
          : id !== null && e instanceof HttpErrorResponse && e.status === 409
            ? 'Only a draft claim can be edited; void it and add a new one instead.'
          : id === null
            ? 'That claim could not be added.'
            : 'That claim could not be saved.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Claim {
  id: number;
  personId: number;
  /** The amount with two decimals, as text (e.g. "10.50"). */
  amount: string;
  /** YYYY-MM-DD */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened (sheet-wide, e.g. "3", or within its
   *  period, e.g. "P1-2", or "X-1" in no period); null while DRAFT. */
  number: string | null;
  /** What was due on the claim when it was settled, with two decimals; null otherwise, and when its
   *  person's grade had no rate then. */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the claim is bound to the figure it had at its person's last statement. */
  stated: boolean;
  /** The figure it is bound to, with two decimals; null while unbound, and when it had no figure
   *  (no rate) then. */
  statedDue: string | null;
  /** On a correction (a claim with a negative amount), the number of the SETTLED claim of the same
   *  person it corrects; null on any other claim. */
  corrects: string | null;
}

/** Added as DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it PENDING
 *  until a steward approves it (SETTLED) or rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim
 *  can be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A status change asked of a claim. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void';

/** Whether a claim in this status counts toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** Whether a claim is still open: OPEN, or PENDING, which is handled like OPEN (it goes overdue,
 *  bears the late charge and leaves the totals while its person is on hold). */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** The date (YYYY-MM-DD) a claim is due by: its date plus the sheet's terms, in days. */
export function dueByOf(claim: Claim, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: OPEN or PENDING, and due by a date before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string | null): boolean {
  return isOpen(claim) && today !== null && dueByOf(claim, terms) < today;
}

/** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
export interface BulkOpened {
  opened: number;
  refused: number;
  claims: Claim[];
}

export interface ClaimFields {
  amount: string;
  /** null takes the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null on a claim that is not a correction. */
  corrects: string | null;
}

/** Whether a claim is a correction: one with a negative amount. */
export function isCorrection(claim: Claim): boolean {
  return cents(claim.amount) < 0;
}

/** Amounts in whole cents, so sums of two-decimal amounts are exact. */
export function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

export function money(cents: number): string {
  return (cents / 100).toFixed(2);
}

// The claims kept on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class ClaimsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's claims, newest first. */
  list(sheet: string): Promise<Claim[]> {
    return firstValueFrom(
      this.http.get<Claim[]>(`${this.url(sheet)}/claims`, { headers: this.session.headers() }),
    );
  }

  add(sheet: string, personId: number, fields: ClaimFields): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheet)}/people/${personId}/claims`, fields, {
        headers: this.session.headers(),
      }),
    );
  }

  update(sheet: string, id: number, fields: ClaimFields): Promise<Claim> {
    return firstValueFrom(
      this.http.put<Claim>(`${this.url(sheet)}/claims/${id}`, fields, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Change the claim's status; refused (409) when its status does not allow the change, (403) when
   *  the user who opened it asks to settle or approve it or one who is not a steward asks to approve or
   *  reject it, and (400) when a reject gives no one-word reason. */
  act(sheet: string, id: number, action: ClaimAction, reason?: string): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheet)}/claims/${id}/${action}`, action === 'reject' ? { reason } : null, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Open each of the claims that can be opened, numbered in list order; the rest are left as they
   *  are and counted as refused. */
  bulkOpen(sheet: string, claimIds: number[]): Promise<BulkOpened> {
    return firstValueFrom(
      this.http.post<BulkOpened>(`${this.url(sheet)}/claims/bulk-open`, { claimIds }, {
        headers: this.session.headers(),
      }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}
-- A clerk's settle of a claim whose due is above the clerk limit leaves it PENDING until a steward
-- approves it (SETTLED) or rejects it (back to OPEN). A PENDING claim counts like an OPEN one.
ALTER TABLE claim DROP CONSTRAINT claim_status;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
-- A claim with a negative amount is a correction: it carries in corrects the number of the SETTLED
-- claim of the same person it corrects; corrects is null on any other claim.
ALTER TABLE claim ADD COLUMN corrects INTEGER;

-- The amount was checked to be 0.00 or more by an unnamed constraint: replace the column (which drops
-- that constraint) so only a correction can be negative.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(12, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

